"""Оформлення виміряних фактів і меж перевірки; живого повтору не запускає."""
import json
from os.path import relpath
from pathlib import Path
import re

Т = Path(__file__).resolve().parent
К = Т.parents[2]
план = json.loads((Т / "план.json").read_text(encoding="utf-8"))
факти = json.loads((Т / "факти.json").read_text(encoding="utf-8"))
місця = {н: Т / н for н in план["scenes"]}
for ф in (К / "аудит/проби/нічні").rglob("походження.json"):
    д = json.loads(ф.read_text(encoding="utf-8"))
    початковий = (К / д["шлях_запису"]).resolve()
    for н in місця:
        if початковий == (Т / н).resolve():
            місця[н] = ф.parent
(Т / "місця_записів.json").write_text(json.dumps({н: str(ф.relative_to(К)) for н, ф in місця.items()}, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")

