матриця = ["# Відповіді на 51 питання", "", "Повні формулювання — у план.json і НАРЯД.md. Кожен рядок нижче відповідає одному питанню у порядку JSON. Одна сцена записана на всі її PR; висновок обмежено реально пройденим шляхом.", "", "| № | Сцена | PR | Відповідь і межа доказу |", "|---|---|---|---|"]
н = 0
for сцена, питання in план["scenes"].items():
    for п in питання:
        н += 1
        текст = відповіді[сцена]
        if п["pr"] == 2632 and сцена.startswith("ж3_кафе"):
            текст = "НЕ ПРОЙШЛО ДЛЯ РЕПЛІКИ: " + текст
